head.script:
scwin.btnOpenPopup_onclick = function(e) {
    openPopup();
};
scwin._hasClass = function(id) {
    if (!WebSquare.wUnit.getDomById($p.id + id)) {
        return false;
    }
    return true;
}
scwin.__isDisabled = function(id) {
    var className = WebSquare.wUnit.getDomById($p.id + id).className;
    return className.indexOf("w2tabcontrol_disabled") >= 0;
}
scwin.setValue = function() {
    if (WebSquare.wUnit.getJq('#popup_closeButton').length == 0) {
        wfm_popup_popup_closeButton.click();
    } else {
        popup_closeButton.click();
    }
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btnOpenPopup').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin._hasClass('wfm_popup')", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "scwin.setValue()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin._hasClass('wfm_popup')", "false");
    WebSquare.wUnit.addCommand("assert", "scwin.__isDisabled('wq_uuid_3_tab_tab2')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__isDisabled('wq_uuid_3_tab_tab3')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    openPopup = function() {
        window.options = {
            "src": "tabControl_Disable_WEF-115_(WSQ-1404)_popup.xml",
            "style": "position:absolute; top:0; width:100%; height:100%; z-index:9001"
        };
        WebSquare.layer.showModal();
        WebSquare.util.dynamicCreate("wfm_popup", "wframe", options);
    };
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 08-Feb-2018
    //End unitTest
}
